// Validate and configure teaser package request
const input = $input.first().json.body || $input.first().json;

// Required fields
const outlineId = input.outline_id;
const topic = input.topic;
const title = input.title;

if (!outlineId) {
  throw new Error('Must provide outline_id from W6');
}

// Package configuration
const packageType = input.package_type || 'full';
const validPackageTypes = ['full', 'social_only', 'video_only', 'landing_page_only'];
if (!validPackageTypes.includes(packageType)) {
  throw new Error(`Invalid package_type: ${packageType}`);
}

// Platform selection
const defaultPlatforms = ['twitter', 'linkedin', 'instagram', 'tiktok', 'youtube'];
const platforms = input.platforms || defaultPlatforms;

// Tone and urgency
const tone = input.tone || 'professional';
const urgencyLevel = input.urgency_level || 'medium';

// Platform-specific configuration
const platformConfig = {
  twitter: {
    maxLength: 280,
    hashtagCount: 3,
    postsNeeded: 5,
    style: 'punchy, thread-friendly'
  },
  linkedin: {
    maxLength: 3000,
    hashtagCount: 5,
    postsNeeded: 3,
    style: 'professional, story-driven'
  },
  instagram: {
    maxLength: 2200,
    hashtagCount: 15,
    postsNeeded: 4,
    style: 'visual-first, carousel-friendly'
  },
  tiktok: {
    maxLength: 300,
    hashtagCount: 5,
    postsNeeded: 3,
    style: 'hook-heavy, trend-aware'
  },
  youtube: {
    maxLength: 5000,
    hashtagCount: 3,
    postsNeeded: 2,
    style: 'SEO-optimized, searchable'
  },
  threads: {
    maxLength: 500,
    hashtagCount: 0,
    postsNeeded: 3,
    style: 'conversational, authentic'
  },
  facebook: {
    maxLength: 63206,
    hashtagCount: 2,
    postsNeeded: 3,
    style: 'community-focused, shareable'
  }
};

// Video configuration
const videoConfig = {
  tiktok_short: {
    duration: '15-60 seconds',
    structure: 'hook (3s) → problem (10s) → solution tease (10s) → CTA (5s)',
    count: 3
  },
  youtube_short: {
    duration: '30-60 seconds',
    structure: 'hook (3s) → value bomb (20s) → cliffhanger (10s) → subscribe CTA',
    count: 3
  },
  youtube_long: {
    duration: '8-12 minutes',
    structure: 'hook → intro → 3 main points → deeper dive → CTA → outro',
    count: 1
  }
};

// Callback configuration
const callbackWorkflow = input.callback_workflow || null;
const autoTriggerImageGen = input.auto_trigger_image_gen !== false;

return [{
  json: {
    outline_id: outlineId,
    topic: topic,
    title: title || topic,
    format: input.format || 'ebook',
    package_type: packageType,
    platforms: platforms,
    platform_config: platformConfig,
    video_config: videoConfig,
    tone: tone,
    urgency_level: urgencyLevel,
    callback_workflow: callbackWorkflow,
    auto_trigger_image_gen: autoTriggerImageGen,
    session_id: `teaser_${Date.now()}_${Math.random().toString(36).substr(2, 9)}`,
    started_at: new Date().toISOString()
  }
}];

// Parse and prepare data for teaser generation
const config = $('Validate & Configure').first().json;
const outline = $('Fetch Outline from W6').first().json;
const research = $input.first().json;

// Parse outline sections
let sections = [];
let allTitles = [];
let derivatives = [];
try { sections = JSON.parse(outline.Sections || '[]'); } catch(e) {}
try { allTitles = JSON.parse(outline['All Titles'] || '[]'); } catch(e) {}
try { derivatives = JSON.parse(outline.Derivatives || '[]'); } catch(e) {}

// Parse research
let insights = [];
let statistics = [];
let quotes = [];
let keyThemes = [];
try { insights = JSON.parse(research.Insights || '[]'); } catch(e) {}
try { statistics = JSON.parse(research.Statistics || '[]'); } catch(e) {}
try { quotes = JSON.parse(research.Quotes || '[]'); } catch(e) {}
try { keyThemes = JSON.parse(research['Key Themes'] || '[]'); } catch(e) {}

// Extract best hooks from sections
const sectionHooks = sections
  .filter(s => s.hooks?.opening)
  .map(s => ({
    section: s.title,
    hook: s.hooks.opening,
    promise: s.hooks.promise
  }));

// Sort insights by importance for marketing use
const topInsights = [...insights]
  .sort((a, b) => (b.importance || 0) - (a.importance || 0))
  .slice(0, 10);

// Get warning/problem insights (pain points for marketing)
const painPoints = insights
  .filter(i => i.category === 'warning' || i.category === 'problem')
  .slice(0, 5);

// Get actionable insights (solutions for marketing)
const solutions = insights
  .filter(i => i.category === 'actionable' || i.category === 'framework')
  .slice(0, 5);

// Build marketing context
const marketingContext = {
  // Core product info
  title: outline.Title || config.title,
  subtitle: outline.Subtitle || '',
  format: outline.Format || config.format,
  section_count: sections.length,
  total_words: outline['Total Target Words'] || 0,
  reading_time: outline['Reading Time (min)'] || 0,

  // Alternative titles for A/B testing
  title_variants: allTitles.slice(0, 5),

  // Section preview (for lead magnet teasers)
  first_sections: sections.slice(0, 3).map(s => ({
    title: s.title,
    key_points: s.key_points?.slice(0, 3) || [],
    hook: s.hooks?.opening
  })),

  // Marketing ammunition
  hooks: sectionHooks.slice(0, 5),
  pain_points: painPoints,
  solutions: solutions,
  top_insights: topInsights,
  statistics: statistics.slice(0, 10),
  expert_quotes: quotes.slice(0, 5),
  key_themes: keyThemes,

  // Derivative products (bonus offerings)
  derivatives: derivatives.slice(0, 5),

  // Research quality (for authority claims)
  research_quality: research['Quality Score'] || 0,
  source_count: (JSON.parse(research.Sources || '[]')).length
};

return [{
  json: {
    ...config,
    marketing: marketingContext,
    outline_record_id: outline.id,
    research_record_id: research.id
  }
}];

