// Parse all generated content
const inputData = $('Parse Marketing Context').first().json;

// Parse social posts
let socialPosts = { social_posts: {} };
try {
  const socialRaw = $('Generate Social Posts').first().json.message?.content || '{}';
  socialPosts = typeof socialRaw === 'string' ? JSON.parse(socialRaw) : socialRaw;
} catch (e) { console.error('Social parse error:', e); }

// Parse video scripts
let videoScripts = { video_scripts: {} };
try {
  const videoRaw = $('Generate Video Scripts').first().json.message?.content || '{}';
  videoScripts = typeof videoRaw === 'string' ? JSON.parse(videoRaw) : videoRaw;
} catch (e) { console.error('Video parse error:', e); }

// Parse landing page
let landingPage = { landing_page: {} };
try {
  const landingRaw = $('Generate Landing Page').first().json.message?.content || '{}';
  landingPage = typeof landingRaw === 'string' ? JSON.parse(landingRaw) : landingRaw;
} catch (e) { console.error('Landing parse error:', e); }

// Parse email & ads
let emailAds = { email_marketing: {}, ad_copy: {}, lead_magnet: {} };
try {
  const emailRaw = $('Generate Email & Ads').first().json.message?.content || '{}';
  emailAds = typeof emailRaw === 'string' ? JSON.parse(emailRaw) : emailRaw;
} catch (e) { console.error('Email/Ads parse error:', e); }

// Count assets generated
const assetCounts = {
  social_posts: Object.values(socialPosts.social_posts || {}).flat().length,
  video_scripts: (
    (videoScripts.video_scripts?.tiktok_reels?.length || 0) +
    (videoScripts.video_scripts?.youtube_shorts?.length || 0) +
    (videoScripts.video_scripts?.youtube_long ? 1 : 0)
  ),
  landing_page_sections: Object.keys(landingPage.landing_page || {}).length,
  email_subjects: emailAds.email_marketing?.subject_lines?.length || 0,
  ad_variants: (
    (emailAds.ad_copy?.facebook_instagram?.length || 0) +
    (emailAds.ad_copy?.google_search?.length || 0)
  )
};

const totalAssets = Object.values(assetCounts).reduce((a, b) => a + b, 0);

// Extract image generation requests
const imageRequests = [];

// From social posts - visual directions
for (const [platform, posts] of Object.entries(socialPosts.social_posts || {})) {
  for (const post of (posts || [])) {
    if (post.visual_direction) {
      imageRequests.push({
        type: 'social_graphic',
        platform: platform,
        direction: post.visual_direction,
        copy_preview: post.copy?.substring(0, 50)
      });
    }
  }
}

// From video scripts - thumbnails
if (videoScripts.video_scripts?.youtube_long?.thumbnail_concept) {
  imageRequests.push({
    type: 'youtube_thumbnail',
    direction: videoScripts.video_scripts.youtube_long.thumbnail_concept
  });
}

// From landing page - hero image
if (landingPage.landing_page?.hero?.hero_image_direction) {
  imageRequests.push({
    type: 'hero_image',
    direction: landingPage.landing_page.hero.hero_image_direction
  });
}

return [{
  json: {
    ...inputData,
    package: {
      social_posts: socialPosts.social_posts || {},
      video_scripts: videoScripts.video_scripts || {},
      landing_page: landingPage.landing_page || {},
      email_marketing: emailAds.email_marketing || {},
      ad_copy: emailAds.ad_copy || {},
      lead_magnet: emailAds.lead_magnet || {}
    },
    asset_counts: assetCounts,
    total_assets: totalAssets,
    image_requests: imageRequests
  }
}];

// Build final teaser package for storage
const data = $input.first().json;

const completedAt = new Date().toISOString();
const durationMs = new Date(completedAt) - new Date(data.started_at);

return [{
  json: {
    // Identifiers
    outline_id: data.outline_id,
    topic: data.topic,
    title: data.marketing.title,
    session_id: data.session_id,

    // Package config
    package_type: data.package_type,
    platforms: JSON.stringify(data.platforms),
    tone: data.tone,
    urgency_level: data.urgency_level,

    // Social posts
    social_posts: JSON.stringify(data.package.social_posts),
    social_post_count: data.asset_counts.social_posts,

    // Video scripts
    video_scripts: JSON.stringify(data.package.video_scripts),
    video_script_count: data.asset_counts.video_scripts,

    // Landing page
    landing_page: JSON.stringify(data.package.landing_page),
    landing_page_sections: data.asset_counts.landing_page_sections,

    // Email marketing
    email_marketing: JSON.stringify(data.package.email_marketing),
    email_subject_count: data.asset_counts.email_subjects,

    // Ad copy
    ad_copy: JSON.stringify(data.package.ad_copy),
    ad_variant_count: data.asset_counts.ad_variants,

    // Lead magnet
    lead_magnet: JSON.stringify(data.package.lead_magnet),

    // Image requests for W13
    image_requests: JSON.stringify(data.image_requests),
    image_request_count: data.image_requests.length,

    // Totals
    total_assets: data.total_assets,

    // Callbacks
    callback_workflow: data.callback_workflow,
    auto_trigger_image_gen: data.auto_trigger_image_gen,

    // Timing
    started_at: data.started_at,
    completed_at: completedAt,
    duration_seconds: Math.round(durationMs / 1000),

    // Status
    status: 'ready'
  }
}];

