// Build comprehensive response
const packageData = $('Build Storage Package').first().json;
const airtableRecord = $('Save to Airtable').first().json;

// Summarize what was generated
const socialSummary = {};
const socialPosts = JSON.parse(packageData.social_posts || '{}');
for (const [platform, posts] of Object.entries(socialPosts)) {
  socialSummary[platform] = (posts || []).length;
}

const videoSummary = {
  tiktok_reels: 0,
  youtube_shorts: 0,
  youtube_long: 0
};
const videoScripts = JSON.parse(packageData.video_scripts || '{}');
videoSummary.tiktok_reels = videoScripts.tiktok_reels?.length || 0;
videoSummary.youtube_shorts = videoScripts.youtube_shorts?.length || 0;
videoSummary.youtube_long = videoScripts.youtube_long ? 1 : 0;

return [{
  json: {
    success: true,
    teaser_package_id: airtableRecord.id,

    // Product info
    title: packageData.title,
    outline_id: packageData.outline_id,

    // Configuration
    config: {
      package_type: packageData.package_type,
      platforms: JSON.parse(packageData.platforms || '[]'),
      tone: packageData.tone,
      urgency_level: packageData.urgency_level
    },

    // Asset summary
    assets_generated: {
      social_posts: {
        total: packageData.social_post_count,
        by_platform: socialSummary
      },
      video_scripts: {
        total: packageData.video_script_count,
        breakdown: videoSummary
      },
      landing_page: {
        sections: packageData.landing_page_sections
      },
      email_marketing: {
        subject_lines: packageData.email_subject_count
      },
      ad_copy: {
        variants: packageData.ad_variant_count
      },
      images_requested: packageData.image_request_count
    },

    // Totals
    total_assets: packageData.total_assets,

    // Timing
    duration_seconds: packageData.duration_seconds,

    // Triggered workflows
    triggered: {
      image_generator: packageData.auto_trigger_image_gen && packageData.image_request_count > 0,
      callback: packageData.callback_workflow || null
    },

    // Links
    links: {
      airtable: `https://airtable.com/appXXXXXXXXXXXXXX/tblMarketing/${airtableRecord.id}`,
      export_social: `/api/teaser/${airtableRecord.id}/export/social`,
      export_video: `/api/teaser/${airtableRecord.id}/export/video`,
      export_landing: `/api/teaser/${airtableRecord.id}/export/landing`
    }
  }
}];
